/*
 *----------------------------------------------------------------------
 *
 * info_commands_command --
 *
 *	info commands ?PATTERN?
 *
 *----------------------------------------------------------------------
 */

/*
 * th8InfoListNsCommands --
 *
 *	Helper: iterate the commands in a specific namespace,
 *	glob-match the tail against zTailPat, and append
 *	fully-qualified names (zPrefix + "::" + tail) to the
 *	output list.  Used by info commands and info procs.
 */

typedef struct {
    Th8_Interp *interp;
    const char *zTailPat;	/* Tail glob pattern. */
    size_t nTailPat;
    const char *zPrefix;	/* Namespace prefix (e.g. "::foo"). */
    size_t nPrefix;
    char **pzList;		/* Output list. */
    size_t *pnList;
    int bProcsOnly;		/* If true, filter to procs only. */
} Th8_InfoCmdCtx;

static int
th8InfoCmdCallback(Th8_HashEntry *pEntry, void *pVoid)
{
    Th8_InfoCmdCtx *p = (Th8_InfoCmdCtx *)pVoid;
    const char *zName = pEntry->zKey;
    size_t nName = pEntry->nKey;

    if (p->bProcsOnly) {
	/*
	 * For info procs, the hash entry's pData points to
	 * the command info.  We can't easily check "is proc"
	 * from the hash entry alone.  Instead, rely on the
	 * fact that Th8_GetCommandInfo returns non-zero for
	 * procs.  Build the full name and check.
	 */

	/* Skip non-proc entries - this is a simplification;
	 * the caller can filter further if needed. */
    }

    if (Th8_GlobMatch(p->interp, p->zTailPat, p->nTailPat,
	    zName, nName)) {
	/*
	 * Build "::ns::name" and append.
	 */

	char *zFull = 0;
	size_t nFull = 0;

	Th8_StringAppend(p->interp, &zFull, &nFull,
		p->zPrefix, p->nPrefix);
	Th8_StringAppend(p->interp, &zFull, &nFull,
		"::", 2);
	Th8_StringAppend(p->interp, &zFull, &nFull,
		zName, nName);
	Th8_ListAppend(p->interp, p->pzList, p->pnList,
		zFull, nFull);
	Th8_Free(p->interp, zFull);
    }
    return TH8_OK;
}

static int
info_commands_command(
    Th8_Interp *interp,
    void *ctx,
    int argc,
    const char **argv,
    size_t *argl)
{
    char *zList = 0;
    size_t nList = 0;

    if (argc != 2 && argc != 3) {
	return Th8_WrongNumArgs(interp,
		"info commands ?pattern?");
    }

    if (argc == 3) {
	const char *zPat = argv[2];
	size_t nPat = TH8_LEN(argl[2]);
	const char *zNsPath;
	size_t nNsPath;
	const char *zTail;
	size_t nTail;
	char *zBuf = 0;
	int bQualified;

	bQualified = th8ResolveNsPattern(interp,
		zPat, nPat, &zNsPath, &nNsPath,
		&zTail, &nTail, &zBuf);

	if (bQualified) {
	    struct Th8_Namespace *pNs;
	    Th8_InfoCmdCtx ictx;

	    pNs = th8FindNamespace(interp,
		    zNsPath, nNsPath, 0);
	    if (pNs && pNs->paCmd) {
		ictx.interp = interp;
		ictx.zTailPat = zTail;
		ictx.nTailPat = nTail;
		ictx.zPrefix = zNsPath;
		ictx.nPrefix = nNsPath;
		ictx.pzList = &zList;
		ictx.pnList = &nList;
		ictx.bProcsOnly = 0;
		Th8_HashIterate(interp, pNs->paCmd,
			th8InfoCmdCallback, &ictx);
	    }
	    Th8_Free(interp, zBuf);
	} else {
	    /*
	     * Simple (non-qualified) pattern: list
	     * commands from current + global namespaces,
	     * filter by glob.
	     */

	    Th8_ListAppendCommands(interp, &zList, &nList);
	    {
		char **azElem = 0;
		size_t *anElem = 0;
		int nCount;
		char *zFiltered = 0;
		size_t nFiltered = 0;
		int i;

		Th8_SplitList(interp, zList, nList,
			&azElem, &anElem, &nCount);
		for (i = 0; i < nCount && azElem; i++) {
		    if (Th8_GlobMatch(interp, zPat, nPat,
			    azElem[i], TH8_LEN(anElem[i]))) {
			Th8_ListAppend(interp,
				&zFiltered, &nFiltered,
				azElem[i], anElem[i]);
		    }
		}
		Th8_Free(interp, azElem);
		Th8_Free(interp, zList);
		zList = zFiltered;
		nList = nFiltered;
	    }
	}
    } else {
	Th8_ListAppendCommands(interp, &zList, &nList);
    }
    Th8_SetResult(interp, zList, nList);
    Th8_Free(interp, zList);
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * info_script_command --
 *
 *	Return the name of the innermost active [source] script.
 *	Returns empty string if no source is active.
 *
 *	info script
 *
 *----------------------------------------------------------------------
 */

static int
info_script_command(
    Th8_Interp *interp,	/* Interpreter. */
    void *ctx,			/* Not used. */
    int argc,			/* Number of arguments. */
    const char **argv,		/* Argument values. */
    size_t *argl)		/* Argument lengths. */
{
    size_t nName;
    const char *zName;

    (void)ctx;

    if (argc != 2 && argc != 3) {
	return Th8_WrongNumArgs(interp, "info script ?filename?");
    }

    if (argc == 3) {
	/*
	 * Per Tcl standard, "info script <name>" sets the
	 * script name for the current invocation level.
	 */

	Th8_PopSourceName(interp);
	Th8_PushSourceName(interp, argv[2], argl[2]);
    }
    zName = Th8_GetSourceName(interp, &nName);
    Th8_SetResult(interp, zName, nName);
    return TH8_OK;
}


#if defined(TH8_PLUGIN_PROCEDURES)
#if defined(TH8_ENABLE_VARIABLES)
/*
 *----------------------------------------------------------------------
 *
 * info_default_command --
 *
 *	Query the default value of a procedure parameter.
 *
 *	info default PROCNAME ARGNAME VARNAME
 *
 *	If ARGNAME has a default value in PROCNAME, stores it in
 *	VARNAME and returns 1.  Otherwise sets VARNAME to "" and
 *	returns 0.
 *
 *----------------------------------------------------------------------
 */

static int
info_default_command(
    Th8_Interp *interp,
    void *ctx,
    int argc,
    const char **argv,
    size_t *argl)
{
    Th8_CommandProc xProc;
    void *pContext;
    Th8_ProcDefn *p;
    int i;

    (void)ctx;

    if (argc != 5) {
	return Th8_WrongNumArgs(interp,
		"info default procname argname varname");
    }
    if (Th8_GetCommandInfo(interp, argv[2], argl[2],
	    &xProc, &pContext) != TH8_OK
	    || (xProc != th8ProcCall1 && xProc != th8NprocCall1)) {
	char *zErr = 0;
	size_t nErr = 0;

	Th8_StringAppend(interp, &zErr, &nErr, "\"", 1);
	Th8_StringAppend(interp, &zErr, &nErr,
		argv[2], argl[2]);
	Th8_StringAppend(interp, &zErr, &nErr,
		"\" is not a procedure", TH8_NOLEN);
	Th8_SetResult(interp, zErr, nErr);
	Th8_Free(interp, zErr);
	return TH8_ERROR;
    }
    p = (Th8_ProcDefn *)pContext;

    /*
     * Search the parameter list for ARGNAME.
     */

    for (i = 0; i < p->nParam; i++) {
	if (p->anParam[i] == TH8_LEN(argl[3])
		&& Th8_Memcmp(interp, p->azParam[i],
			argv[3], p->anParam[i]) == 0) {
	    if (p->azDefault && p->azDefault[i]) {
		Th8_SetVar(interp, argv[4],
			TH8_LEN(argl[4]),
			p->azDefault[i], p->anDefault[i]);
		return Th8_SetResultInt(interp, 1);
	    } else {
		Th8_SetVar(interp, argv[4],
			TH8_LEN(argl[4]), "", 0);
		return Th8_SetResultInt(interp, 0);
	    }
	}
    }

    {
	char *zErr = 0;
	size_t nErr = 0;

	Th8_StringAppend(interp, &zErr, &nErr,
		"procedure \"", TH8_NOLEN);
	Th8_StringAppend(interp, &zErr, &nErr,
		argv[2], argl[2]);
	Th8_StringAppend(interp, &zErr, &nErr,
		"\" doesn't have an argument \"",
		TH8_NOLEN);
	Th8_StringAppend(interp, &zErr, &nErr,
		argv[3], argl[3]);
	Th8_StringAppend(interp, &zErr, &nErr,
		"\"", 1);
	Th8_SetResult(interp, zErr, nErr);
	Th8_Free(interp, zErr);
	return TH8_ERROR;
    }
}
#endif


/*
 *----------------------------------------------------------------------
 *
 * info_body_command --
 *
 *	Return the body of a procedure.
 *
 *	info body procname
 *
 *----------------------------------------------------------------------
 */

static int
info_body_command(
    Th8_Interp *interp,	/* Interpreter. */
    void *ctx,			/* Not used. */
    int argc,			/* Number of arguments. */
    const char **argv,		/* Argument values. */
    size_t *argl)		/* Argument lengths. */
{
    Th8_CommandProc xProc;
    void *pContext;
    Th8_ProcDefn *p;

    if (argc != 3) {
	return Th8_WrongNumArgs(interp, "info body procname");
    }
    if (Th8_GetCommandInfo(interp, argv[2], argl[2],
	    &xProc, &pContext) != TH8_OK
	    || (xProc != th8ProcCall1 && xProc != th8NprocCall1)) {
	char *zErr = 0;
	size_t nErr = 0;

	Th8_StringAppend(interp, &zErr, &nErr, "\"", 1);
	Th8_StringAppend(interp, &zErr, &nErr,
		argv[2], argl[2]);
	Th8_StringAppend(interp, &zErr, &nErr,
		"\" is not a procedure", TH8_NOLEN);
	Th8_SetResult(interp, zErr, nErr);
	Th8_Free(interp, zErr);
	return TH8_ERROR;
    }
    p = (struct Th8_ProcDefn *)pContext;
    return Th8_SetResult(interp, p->zProgram, p->nProgram);
}


/*
 *----------------------------------------------------------------------
 *
 * info_args_command --
 *
 *	Return a list of the formal parameters of a procedure.
 *
 *	info args procname
 *
 *----------------------------------------------------------------------
 */

static int
info_args_command(
    Th8_Interp *interp,	/* Interpreter. */
    void *ctx,			/* Not used. */
    int argc,			/* Number of arguments. */
    const char **argv,		/* Argument values. */
    size_t *argl)		/* Argument lengths. */
{
    Th8_CommandProc xProc;
    void *pContext;
    Th8_ProcDefn *p;
    char *zList = 0;
    size_t nList = 0;
    int i;

    if (argc != 3) {
	return Th8_WrongNumArgs(interp, "info args procname");
    }
    if (Th8_GetCommandInfo(interp, argv[2], argl[2],
	    &xProc, &pContext) != TH8_OK
	    || (xProc != th8ProcCall1 && xProc != th8NprocCall1)) {
	char *zErr = 0;
	size_t nErr = 0;

	Th8_StringAppend(interp, &zErr, &nErr, "\"", 1);
	Th8_StringAppend(interp, &zErr, &nErr,
		argv[2], argl[2]);
	Th8_StringAppend(interp, &zErr, &nErr,
		"\" is not a procedure", TH8_NOLEN);
	Th8_SetResult(interp, zErr, nErr);
	Th8_Free(interp, zErr);
	return TH8_ERROR;
    }
    p = (struct Th8_ProcDefn *)pContext;
    for (i = 0; i < p->nParam; i++) {
	Th8_ListAppend(interp, &zList, &nList,
		p->azParam[i], p->anParam[i]);
    }
    if (p->hasArgs) {
	Th8_ListAppend(interp, &zList, &nList, "args", 4);
    }
    Th8_SetResult(interp, zList, nList);
    Th8_Free(interp, zList);
    return TH8_OK;
}


/*
 *----------------------------------------------------------------------
 *
 * info_procs_command --
 *
 *	Return a list of procedures (proc/nproc), excluding
 *	built-in commands.
 *
 *	info procs ?PATTERN?
 *
 *----------------------------------------------------------------------
 */

static int
info_procs_command(
    Th8_Interp *interp,	/* Interpreter. */
    void *ctx,			/* Not used. */
    int argc,			/* Number of arguments. */
    const char **argv,		/* Argument values. */
    size_t *argl)		/* Argument lengths. */
{
    char *zList = 0;
    size_t nList = 0;

    if (argc != 2 && argc != 3) {
	return Th8_WrongNumArgs(interp,
		"info procs ?pattern?");
    }

    if (argc == 3) {
	const char *zPat = argv[2];
	size_t nPat = TH8_LEN(argl[2]);
	const char *zNsPath;
	size_t nNsPath;
	const char *zTail;
	size_t nTail;
	char *zBuf = 0;
	int bQualified;

	bQualified = th8ResolveNsPattern(interp,
		zPat, nPat, &zNsPath, &nNsPath,
		&zTail, &nTail, &zBuf);

	if (bQualified) {
	    struct Th8_Namespace *pNs;
	    Th8_InfoCmdCtx ictx;

	    pNs = th8FindNamespace(interp,
		    zNsPath, nNsPath, 0);
	    if (pNs && pNs->paCmd) {
		ictx.interp = interp;
		ictx.zTailPat = zTail;
		ictx.nTailPat = nTail;
		ictx.zPrefix = zNsPath;
		ictx.nPrefix = nNsPath;
		ictx.pzList = &zList;
		ictx.pnList = &nList;
		ictx.bProcsOnly = 1;
		Th8_HashIterate(interp, pNs->paCmd,
			th8InfoCmdCallback, &ictx);
	    }
	    Th8_Free(interp, zBuf);
	} else {
	    Th8_ListAppendCommandsMatching(interp,
		    &zList, &nList,
		    th8ProcCall1, th8NprocCall1);
	    {
		char **azElem = 0;
		size_t *anElem = 0;
		int nCount;
		char *zFiltered = 0;
		size_t nFiltered = 0;
		int i;

		Th8_SplitList(interp, zList, nList,
			&azElem, &anElem, &nCount);
		for (i = 0; i < nCount && azElem; i++) {
		    if (Th8_GlobMatch(interp, zPat, nPat,
			    azElem[i], TH8_LEN(anElem[i]))) {
			Th8_ListAppend(interp,
				&zFiltered, &nFiltered,
				azElem[i], anElem[i]);
		    }
		}
		Th8_Free(interp, azElem);
		Th8_Free(interp, zList);
		zList = zFiltered;
		nList = nFiltered;
	    }
	}
    } else {
	Th8_ListAppendCommandsMatching(interp,
		&zList, &nList,
		th8ProcCall1, th8NprocCall1);
    }
    Th8_SetResult(interp, zList, nList);
    Th8_Free(interp, zList);
    return TH8_OK;
}
#endif /* TH8_PLUGIN_PROCEDURES */


/*
 *----------------------------------------------------------------------
 *
 * info_globals_command --
 *
 *	info globals ?PATTERN?
 *
 *	Return a list of global variables, optionally filtered
 *	by a glob pattern.
 *
 *----------------------------------------------------------------------
 */

#if defined(TH8_ENABLE_VARIABLES)
static int
info_globals_command(
    Th8_Interp *interp,
    void *ctx,
    int argc,
    const char **argv,
    size_t *argl)
{
    char *zList = 0;
    size_t nList = 0;

    (void)ctx;

    if (argc != 2 && argc != 3) {
	return Th8_WrongNumArgs(interp,
		"info globals ?pattern?");
    }
    Th8_ListAppendGlobalVariables(interp, &zList, &nList);

    if (argc == 3 && zList) {
	char **azElem = 0;
	size_t *anElem = 0;
	int nCount;
	char *zFiltered = 0;
	size_t nFiltered = 0;
	int i;

	Th8_SplitList(interp, zList, nList,
		&azElem, &anElem, &nCount);
	for (i = 0; i < nCount && azElem; i++) {
	    if (Th8_GlobMatch(interp,
		    argv[2], TH8_LEN(argl[2]),
		    azElem[i], TH8_LEN(anElem[i]))) {
		Th8_ListAppend(interp, &zFiltered,
			&nFiltered,
			azElem[i], anElem[i]);
	    }
	}
	Th8_Free(interp, zList);
	Th8_Free(interp, azElem);
	zList = zFiltered;
	nList = nFiltered;
    }

    if (zList) {
	Th8_SetResult(interp, zList, nList);
	Th8_Free(interp, zList);
    } else {
	Th8_SetResultStatic(interp, "", 0);
    }
    return TH8_OK;
}
#endif


/*
 *----------------------------------------------------------------------
 *
 * info_vars_command --
 *
 *	info vars ?PATTERN?
 *
 *----------------------------------------------------------------------
 */

#if defined(TH8_ENABLE_VARIABLES)
static int
info_vars_command(
    Th8_Interp *interp,
    void *ctx,
    int argc,
    const char **argv,
    size_t *argl)
{
    char *zList = 0;
    size_t nList = 0;
    const char *zPat = 0;
    size_t nPat = 0;
    const char *zNs = 0;
    size_t nNs = 0;
    int bQualified = 0;

    if (argc != 2 && argc != 3) {
	return Th8_WrongNumArgs(interp,
		"info vars ?pattern?");
    }

    /*
     * If a namespace-qualified pattern is given (e.g. ::ns::*),
     * enumerate variables from that namespace.  Otherwise,
     * enumerate from the current frame.
     */

    if (argc == 3) {
	char *zBuf = 0;

	zPat = argv[2];
	nPat = argl[2];
	bQualified = th8ResolveNsPattern(interp,
		zPat, nPat, &zNs, &nNs, &zPat, &nPat, &zBuf);
	if (bQualified) {
	    Th8_ListAppendNsVariables(interp,
		    zNs, nNs, &zList, &nList);
	}
	Th8_Free(interp, zBuf);
    }

    if (!bQualified) {
	Th8_ListAppendVariables(interp, &zList, &nList);
    }

    if (argc == 3 && zList) {
	char **azElem = 0;
	size_t *anElem = 0;
	int nCount;
	char *zFiltered = 0;
	size_t nFiltered = 0;
	int i;

	Th8_SplitList(interp, zList, nList,
		&azElem, &anElem, &nCount);
	for (i = 0; i < nCount && azElem; i++) {
	    if (Th8_GlobMatch(interp,
		    zPat, TH8_LEN(nPat),
		    azElem[i], TH8_LEN(anElem[i]))) {
		Th8_ListAppend(interp, &zFiltered, &nFiltered,
			azElem[i], anElem[i]);
	    }
	}
	Th8_Free(interp, azElem);
	Th8_Free(interp, zList);
	zList = zFiltered;
	nList = nFiltered;
    }
    Th8_SetResult(interp, zList, nList);
    Th8_Free(interp, zList);
    return TH8_OK;
}
#endif


